+    XCTAssertFalse(
+      label.hasPrefix("Current \(Self.wrongRefNoun)"),
+      "the caption must not say \(Self.wrongRefNoun); got \(label)")
+    XCTAssertTrue(label.contains("feature/login"), "the name must be spoken too; got \(label)")
+  }
