+  enum State: Equatable {
+    case idle
+    case loading
+    case loaded
+    case failed(String)
+
+    var isSettled: Bool {
+      switch self {
+      case .loaded, .failed: return true
+      case .idle, .loading: return false
+      }
+    }
+  }
+
