+        "git": CommandResult(
+          stdout: "git version 2.55.0", stderr: "", exitCode: 0,
+          timedOut: false)
+      ])
+    _ = await VCSToolVersions.probe(runner: runner, probeJJ: false)
+    let calls = await runner.calls()
+    XCTAssertEqual(calls.first?.args, ["--version"])
+  }
