+    XCTAssertEqual(VCSToolbarMetrics.outerInset, headerInset)
+    XCTAssertEqual(VCSToolbarMetrics.glyphSlot, headerGlyphSlot)
+    XCTAssertEqual(VCSToolbarMetrics.glyphSpacing, headerSpacing)
